css:
.d-timestamp-seconds-converter{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-timestamp-seconds-converter *,.d-timestamp-seconds-converter *::before,.d-timestamp-seconds-converter *::after{box-sizing:border-box}
.d-timestamp-seconds-converter [hidden]{display:none!important}
.d-timestamp-seconds-converter .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-timestamp-seconds-converter .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-timestamp-seconds-converter label{display:block;margin:8px 0}
.d-timestamp-seconds-converter input,.d-timestamp-seconds-converter select,.d-timestamp-seconds-converter textarea,.d-timestamp-seconds-converter button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-timestamp-seconds-converter input:not([type=checkbox]):not([type=radio]),.d-timestamp-seconds-converter select,.d-timestamp-seconds-converter textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-timestamp-seconds-converter button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-timestamp-seconds-converter button:disabled{opacity:.5;cursor:default}
.d-timestamp-seconds-converter :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-timestamp-seconds-converter [aria-invalid=true]{border-color:var(--warn)!important}
.d-timestamp-seconds-converter .d-scroll{max-width:100%;overflow:auto}
.d-timestamp-seconds-converter table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-timestamp-seconds-converter th,.d-timestamp-seconds-converter td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-timestamp-seconds-converter caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-timestamp-seconds-converter progress{width:100%;accent-color:var(--ink)}
.d-timestamp-seconds-converter pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-timestamp-seconds-converter h3,.d-timestamp-seconds-converter p{margin:8px 0}
.d-timestamp-seconds-converter [aria-pressed=true],.d-timestamp-seconds-converter [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-timestamp-seconds-converter .d-grow{flex:1;min-width:100px}
.d-timestamp-seconds-converter summary{cursor:pointer;padding:6px 0}
.d-timestamp-seconds-converter ul,.d-timestamp-seconds-converter ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-seconds]').step='.001';q('[data-to-seconds]').onclick=()=>{const match=/^(\d{1,5}):([0-5]\d):([0-5]\d(?:\.\d{1,3})?)$/.exec(q('[data-stamp]').value.trim());if(!match){say('时间戳须为 时:分:秒，可带三位小数');return;}q('[data-seconds]').value=String(Number(match[1])*3600+Number(match[2])*60+Number(match[3]));say('时间戳已换算为秒');};q('[data-to-stamp]').onclick=()=>{const n=Number(q('[data-seconds]').value);if(!q('[data-seconds]').value.trim()||!Number.isFinite(n)||n<0||n>359999999){say('请输入 0–359999999 之间的秒数');return;}const ms=Math.round(n*1000),whole=Math.floor(ms/1000);q('[data-stamp]').value=String(Math.floor(whole/3600)).padStart(2,'0')+':'+String(Math.floor(whole/60)%60).padStart(2,'0')+':'+String(whole%60).padStart(2,'0')+'.'+String(ms%1000).padStart(3,'0');say('秒数已换算为时间戳');};})(root, q, qa, say);
}
